insert into public.services (id, name, kicker, summary, includes, pitch, image, sort_order) values ('custom-design', 'CUSTOM DESIGN', 'IDEATE', 'From a napkin sketch to a full build sheet. We draw it before we cut it.', array['Design consultation','Concept renders','Build sheet & estimate']::text[], array['From concept to build.','We bring your vision to life.']::text[], '{"src":"/assets/service/custom-design.png","alt":"A builder sketching a custom motorcycle on a workshop bench","focus":"62% 50%"}'::jsonb, 0) on conflict do nothing;
insert into public.services (id, name, kicker, summary, includes, pitch, image, sort_order) values ('consultation', 'CONSULTATION', 'TALK', 'Sit down with a builder. Bring the bike, the idea, or both.', array['45-minute session','Parts & compatibility advice','Budget planning']::text[], array['Personalised guidance.','Right parts, right look, right for you.']::text[], '{"src":"/assets/service/consultation.png","alt":"A Garage 27 builder talking through a build with a customer","focus":"60% 45%"}'::jsonb, 1) on conflict do nothing;
insert into public.services (id, name, kicker, summary, includes, pitch, image, sort_order) values ('doorstep-installation', 'DOORSTEP INSTALLATION', 'WE COME TO YOU', 'Bolt-on parts fitted at your place by a Garage 27 technician.', array['Bolt-on part fitting','Torque & safety check','Old parts bagged & returned']::text[], array['Skilled hands. Real experience.','We come to you.']::text[], '{"src":"/assets/service/doorstep-installation.png","alt":"A Garage 27 technician fitting parts to a motorcycle at a customer’s home","focus":"58% 50%"}'::jsonb, 2) on conflict do nothing;
insert into public.services (id, name, kicker, summary, includes, pitch, image, sort_order) values ('paint-upholstery', 'CUSTOM PAINT & UPHOLSTERY', 'FINISH', 'Hand-laid paint, pinstripe and leatherwork, done in-house.', array['Paint & pinstripe','Seat re-trim','Tank & panel refinishing']::text[], array['Make it truly yours.','Colors, textures, finishes that speak your style.']::text[], '{"src":"/assets/service/custom-paint-upholstery.png","alt":"A custom-painted flame tank being finished in the paint bay","focus":"55% 50%"}'::jsonb, 3) on conflict do nothing;
insert into public.services (id, name, kicker, summary, includes, pitch, image, sort_order) values ('detailing-restoration', 'DETAILING & RESTORATION', 'REVIVE', 'Bring an old soul back. Strip, restore, protect.', array['Deep detailing','Chrome & metal restoration','Mechanical refresh']::text[], array['Keep it legendary.','From daily care to full restorations.']::text[], '{"src":"/assets/service/detailing-restoration.png","alt":"A gloved hand polishing a spoked wheel and brake disc","focus":"50% 50%"}'::jsonb, 4) on conflict do nothing;
